namespace HybridCPU_ISE.Tests.Architecture;
public sealed class Rf129bgAssistEpochAuthorityDecisionTests
{[Fact] public void PaperSeparatesLocalAssistFreshnessFromRemoteDonorObservation(){string p=File.ReadAllText(Path.Combine(Root(),"ResearchPaper","section","md base","6_Assist_Coupled_Data_Movement_and_Donor_Semantics.md"));Assert.Contains("do not form one universal epoch",p,StringComparison.Ordinal);Assert.Contains("valid initial value after runtime reset",p,StringComparison.Ordinal);Assert.Contains("retained compatibility form for no explicit donor-epoch observation",p,StringComparison.Ordinal);Assert.Contains("no common checked `AssistEpoch` type",p,StringComparison.Ordinal);Assert.Contains("cross-core equality authority",p,StringComparison.Ordinal);}private static string Root(){DirectoryInfo? c=new(AppContext.BaseDirectory);while(c is not null){if(Directory.Exists(Path.Combine(c.FullName,"ResearchPaper")))return c.FullName;c=c.Parent;}throw new DirectoryNotFoundException();}}
